"""Build the executable OMNI frontal candidate expansion notebook."""
import nbformat as nb

b = nb.v4.new_notebook()
md, code = nb.v4.new_markdown_cell, nb.v4.new_code_cell
b.cells = [
    md('# 16.9 - OMNI frontal candidate expansion and split audit\n\nThis notebook expands a 36-image pilot to all 724 source filename suffix-1 candidates. The suffix prioritizes review; it is not a view or clinical label. The original archive remains immutable and test data remain closed.'),
    code('from pathlib import Path\nimport sys, json\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom IPython.display import display\nroot = Path.cwd().resolve()\nwhile not (root / "AGENTS.md").exists():\n    if root == root.parent: raise RuntimeError("Project root not found")\n    root = root.parent\nsys.path.insert(0, str(root / "src/scripts"))\nfrom prepare_omni_frontal_candidates import main as prepare\nfrom audit_omni_frontal_candidates import main as audit\nprint("Root:", root)'),
    md('## 1. Verify and extract\n\nThe shared preparation function checks the original ZIP SHA-256 and every image SHA-256 against the source queue, preserves train/validation membership, and refuses to overwrite changed images or prior review decisions. Run it locally only.'),
    code('prepare()\nbase = root / "data/processed/alignment_omni_frontal_candidates"\nqueue = pd.read_csv(base / "review_queue.csv", dtype={"source_image_id": str, "sha256": str})\nassert len(queue) == 724\ndisplay(queue.groupby("split").agg(images=("source_image_id", "count"), source_folders=("source_folder_1", "nunique"), TM_source_boxes=("tm_boxes", "sum")))'),
    md('## 2. Measure source overlap\n\nExact hashes catch identical image bytes. The first source folder is only a grouping clue, not a verified patient identifier. A low dHash distance creates candidates for visual inspection; it does not prove the same scene.'),
    code('audit()\nreport = root / "docs/reports/alignment/omni_frontal_candidate_audit"\nsummary = json.loads((report / "summary.json").read_text())\ndisplay(pd.DataFrame([summary]).T.rename(columns={0:"value"}))\npairs = pd.read_csv(report / "near_duplicate_review.csv")\nif len(pairs):\n    display(pairs.groupby("dhash_distance").size().to_frame("candidate_pairs"))\n    pairs.dhash_distance.value_counts().sort_index().plot.bar(title="Cross-split dHash candidate distances")\n    plt.xlabel("dHash distance"); plt.ylabel("pairs"); plt.show()'),
    md('## 3. Inspect candidate pairs\n\nThe first visual pairs include nonmatching mouths despite small dHash distance. Retain the conservative train exclusion list until review. This screen cannot certify patient independence.'),
    code('from PIL import Image\nimage = Image.open(report / "near_duplicate_first12.jpg")\nprint("Review montage:", image.size, "pixels")\ndisplay(image.resize((600, image.height)))\nexclusions = pd.read_csv(report / "conservative_train_exclusions.csv", dtype=str)\nprint("Pending train exclusions:", len(exclusions))'),
    md('## 4. Readiness and provenance\n\nAll clinical target states still require a qualified reviewer. The 36 priority images remain useful for checking box definitions. Confirm image redistribution rights before Kaggle publication. The source-label `TM` is broad and cannot be mapped directly to either target.'),
    code('from audit_frontal_review import audit as review_audit\nstate = review_audit(base / "review_queue.csv", base / "boxes_template.csv")\nprint("Reviewed candidates:", state["reviewed_candidates"], "| approved boxes:", state["boxes"], "| consistency issues:", len(state["issues"]))\nassert state["reviewed_candidates"] == 0 if state["boxes"] == 0 else True\nprint("Next: qualified review, overlap resolution, rights verification, then locked frontal training data.")'),
    md('## Implementation appendix\n\nThe source code below is the exact reusable preparation and overlap implementation used above. Its scripts remain the single editable implementation.'),
    code('from IPython.display import Code\nfor filename in ("prepare_omni_frontal_candidates.py", "audit_omni_frontal_candidates.py"):\n    path = root / "src/scripts" / filename\n    print(filename)\n    display(Code(path.read_text(encoding="utf-8"), language="python"))'),
]
b.metadata.kernelspec = {'display_name':'DentalSelfie','language':'python','name':'dentalselfie-local'}
nb.write(b, 'notebooks/alignment/16_9_frontal_candidate_expansion.ipynb')
